import React, { useEffect, useState, useRef } from 'react';
import { connectToNakama } from './api';

function App() {
  const [gameState, setGameState] = useState(null);
  const [matchId, setMatchId] = useState(null);
  const [myId, setMyId] = useState("");
  const [searching, setSearching] = useState(false);
  const [error, setError] = useState("");
  const socketRef = useRef(null);

  useEffect(() => {
    connectToNakama().then(({ session, socket }) => {
      socketRef.current = socket;
      setMyId(session.user_id);

      socket.onmatchmakermatched = async (matched) => {
      console.log('Matched!', matched);
  try {
    const matchId = matched.match_id.split('.')[0];
    const token = matched.token;
    console.log('Trying joinMatch with id:', matchId, 'token:', token);
    const match = await socket.joinMatch(matchId, token);
    console.log('Joined match:', match);
    setMatchId(match.id);
    setSearching(false);
  } catch (e) {
    console.error('Join failed:', e);
    setError('Failed: ' + JSON.stringify(e));
    setSearching(false);
  }
};

      socket.onmatchdata = (result) => {
        const data = JSON.parse(new TextDecoder().decode(result.data));
        console.log("Game state:", data);
        setGameState(data);
      };

    }).catch(err => {
      console.error("Connect failed:", err);
      setError("Connection failed: " + JSON.stringify(err));
    });
  }, []);

  const findGame = () => {
    setSearching(true);
    setError("");
    socketRef.current.addMatchmaker("*", 2, 2);
  };

  const makeMove = (index) => {
    if (!matchId || !gameState || gameState.winner) return;
    if (gameState.currentTurn !== myId) return;
    if (gameState.board[index] !== "") return;
    socketRef.current.sendMatchState(matchId, 1, JSON.stringify({ cell: index }));
  };

  if (error) {
    return (
      <div style={{padding:20, color:'red'}}>
        <h2>Error</h2>
        <pre>{error}</pre>
        <button onClick={() => window.location.reload()}>Reload</button>
      </div>
    );
  }

  if (!matchId) {
    return (
      <div style={{padding:20, textAlign:'center'}}>
        <h1>Multiplayer Tic-Tac-Toe</h1>
        <p style={{color:'#666'}}>My ID: {myId}</p>
        <button onClick={findGame} disabled={searching} style={{padding:'12px 24px', fontSize:16}}>
          {searching ? "Searching for Opponent..." : "Find Match"}
        </button>
      </div>
    );
  }

  if (!gameState) {
    return <div style={{padding:20}}>Initializing Game... (Match: {matchId})</div>;
  }

  return (
    <div style={{padding:20, textAlign:'center'}}>
      <h2>
        {gameState.winner
          ? (gameState.winner === "draw" ? "Draw!" : `Winner: ${gameState.winner}`)
          : (gameState.currentTurn === myId ? "YOUR TURN" : "Opponent's turn")}
      </h2>
      <p style={{fontSize:12, color:'#666'}}>
        You are: {gameState.playerX === myId ? 'X' : 'O'} | Match: {matchId.substring(0,8)}
      </p>
      <div style={{display:'grid', gridTemplateColumns:'repeat(3, 100px)', gap:5, justifyContent:'center', margin:'20px auto'}}>
        {gameState.board.map((cell, i) => (
          <button
            key={i}
            onClick={() => makeMove(i)}
            style={{
              width:100, height:100, fontSize:32, fontWeight:'bold',
              background: cell === 'X' ? '#ffe0e0' : cell === 'O' ? '#e0e0ff' : '#f5f5f5',
              border:'2px solid #ccc', borderRadius:8, cursor:'pointer',
              color: cell === 'X' ? '#e00' : '#00e'
            }}
          >
            {cell}
          </button>
        ))}
      </div>
      {gameState.winner && (
        <button onClick={() => window.location.reload()} style={{padding:'10px 20px', fontSize:16}}>
          Play Again
        </button>
      )}
    </div>
  );
}

export default App;
